package got.wildlife;
import net.minecraft.nbt.CompoundTag; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.entity.animal.Parrot; import net.minecraft.world.level.Level;
public final class GOTButterflyEntity extends Parrot { public enum ButterflyType{COMMON,QOHOR,SOTHORYOS,ULTHOS} private ButterflyType type=ButterflyType.COMMON; private int skin=0; public GOTButterflyEntity(EntityType<? extends Parrot> t,Level l){super(t,l);xpReward=0;} public static AttributeSupplier.Builder createAttributes(){return Parrot.createAttributes().add(Attributes.MAX_HEALTH,2).add(Attributes.FLYING_SPEED,.12).add(Attributes.MOVEMENT_SPEED,.08);} public ButterflyType getButterflyType(){return type;} public int getSkin(){return skin;} public void setButterflyType(ButterflyType t){type=t;} @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);n.putString("GOTButterflyType",type.name());n.putInt("GOTButterflySkin",skin);} @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);try{type=ButterflyType.valueOf(n.getString("GOTButterflyType"));}catch(Exception e){type=ButterflyType.COMMON;}skin=n.getInt("GOTButterflySkin");} @Override public SpawnGroupData finalizeSpawn(net.minecraft.world.level.ServerLevelAccessor l,net.minecraft.world.DifficultyInstance d,MobSpawnType r,SpawnGroupData g,CompoundTag t){skin=l.getRandom().nextInt(5);return super.finalizeSpawn(l,d,r,g,t);} }